css:
/* Global Styles */
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    min-height: 100vh;

}

/* Container */
.container {
    max-width: 100%;
    margin: 0 auto;
    padding: 30px;
    margin: 0 auto; /* Center the container */

}

/* Logo Section */
.logo-container {
    display: flex;
    gap: 15px;
    margin-top:-30px;
    padding: 10px 20px;
    align-items: center; /* Centers content horizontally */
    justify-content: center; /* Centers content vertically if needed */
    text-align: center;
    margin-bottom: 20px;
}
.logo {
    max-width: 80px;
    height: auto;
}
.logo-container h1 {
    font-size: 36px; /* Adjust size as needed */
    font-weight: bold;
    text-align: center; /* Ensure it's centered */
}
.highlight {
    color: #2a2a2a;
}

/* Header */
.header {
    display: flex;
    justify-content: space-between;
    margin-bottom: 30px;
    font-size: 16px; /* Adjust size as needed */
    line-height: 1.8;
    align-items: flex-start;

    width: 100%;
    padding: 10px 0;


}

.details-left {
    text-align: left;
}
.details-right {
    text-align: right;
}
.details {
    font-size: 16px;
    line-height: 1.8;
}

/* Title */
.title {
    text-align: center;
    margin-bottom: 30px;
    margin-top: -30px;
}

/* Table */
.table {
    max-width: 100%;
    margin: 0 auto;
    border-collapse: collapse;
    margin-top: 30px;
    font-size: 16px;
}
.table-bordered th, .table-bordered td {
    border: 1px solid #000;
    padding: 8px;
    text-align: left;
}
.table-bordered th {
    background-color: #2b2a28;
    text-align: center;
    color: white;
}
.table-bordered tbody tr:nth-child(even) {
    background-color: #f2f2f2;
}
